TENSORFLOW_COMPONENT_NAMES = frozenset(
    class_name
    for class_name, (_, _, check_installation_setup) in OPTIONAL_COMPONENTS.items()
    if check_installation_setup
)
SKLEARN_CLASSIFIER_NAMES = frozenset(
    {
        "LogisticRegressionClassifier",
        "SklearnIntentClassifier",
    }
)
_AVAILABILITY_FLAG_TO_COMPONENT: dict[str, tuple[str, str, bool]] = {
    flag: (module_name, class_name, check_installation_setup)
    for class_name, (flag, module_name, check_installation_setup) in (
        OPTIONAL_COMPONENTS.items()
    )
}


def _get_conditional_component(
    module_name: str, class_name: str, check_installation_setup: bool = False
) -> tuple[Optional[Any], bool]:
    """Lazily import a component and cache the result."""
    cache_key = f"{module_name}.{class_name}"
    if cache_key not in _CONDITIONAL_IMPORTS_CACHE:
        _CONDITIONAL_IMPORTS_CACHE[cache_key] = conditional_import(
            module_name, class_name, check_installation_setup
        )
    return _CONDITIONAL_IMPORTS_CACHE[cache_key]


def _build_default_components() -> List[Type[Any]]:
    """Build the list of default components, deferring conditional imports."""
    # Base components that are always available (no external dependencies)
    components: List[Type[Any]] = [
        # Classifiers
        FallbackClassifier,
        KeywordIntentClassifier,
        NLUCommandAdapter,
        LLMCommandGenerator,
        LLMBasedRouter,
        IntentBasedRouter,
        # Entity Extractors
        DucklingEntityExtractor,
        EntitySynonymMapper,
        RegexEntityExtractor,
        # Featurizers
        CountVectorsFeaturizer,
        RegexFeaturizer,
        # Tokenizers
        WhitespaceTokenizer,
        # Language Model Providers
        # Policies
        RulePolicy,
        MemoizationPolicy,
        AugmentedMemoizationPolicy,
        FlowPolicy,
        EnterpriseSearchPolicy,
        IntentlessPolicy,
    ]

    for class_name, (
        _,
        module_name,
        check_installation_setup,
    ) in OPTIONAL_COMPONENTS.items():
        clazz, available = _get_conditional_component(
            module_name, class_name, check_installation_setup
        )
        if available:
            components.append(clazz)

    return components


def __getattr__(name: str) -> Any:
    # Module-level __getattr__ (PEP 562) provides lazy loading for DEFAULT_COMPONENTS
    # and all _AVAILABLE flags, deferring the expensive conditional_import calls.
    if name == "DEFAULT_COMPONENTS":
        global _DEFAULT_COMPONENTS_CACHE
        if _DEFAULT_COMPONENTS_CACHE is None:
            _DEFAULT_COMPONENTS_CACHE = _build_default_components()
        return _DEFAULT_COMPONENTS_CACHE

    if name in _AVAILABILITY_FLAG_TO_COMPONENT:
        module_name, class_name, check_setup = _AVAILABILITY_FLAG_TO_COMPONENT[name]
        _, available = _get_conditional_component(module_name, class_name, check_setup)
        return available

    raise AttributeError(f"module '{__name__}' has no attribute '{name}'")


if TYPE_CHECKING:
    # Provide typed stubs for names served via __getattr__ so mypy can type-check
    # callers that iterate or subscript these values.
    DEFAULT_COMPONENTS: List[Type[Any]]
